//! What the marshalling emitters share. Generated files are never reformatted,
//! so the emitter does its own line breaking.

use heck::ToSnakeCase;
use std::collections::{BTreeMap, BTreeSet};
use std::io::Write;

pub const WIDTH: usize = 100;
const DOC_WIDTH: usize = 80;

pub fn header(script: &str) -> String {
    format!(
        "// @generated by api_gen - DO NOT EDIT. Regenerate with {}.\n",
        script
    )
}

pub fn write_doc(f: &mut impl Write, text: &str) -> std::io::Result<()> {
    let words: Vec<String> = text.split_whitespace().map(str::to_owned).collect();
    write_wrapped(f, "///", DOC_WIDTH, &words)
}

/// Emit items space-separated behind prefix, breaking before width.
fn write_wrapped(
    f: &mut impl Write,
    prefix: &str,
    width: usize,
    items: &[String],
) -> std::io::Result<()> {
    let mut line = String::from(prefix);
    for item in items {
        if line.len() + 1 + item.len() > width {
            writeln!(f, "{}", line)?;
            line = String::from(prefix);
        }
        line.push(' ');
        line.push_str(item);
    }
    writeln!(f, "{}", line)
}

/// The reader a record is read back through, on either side of the ABI.
pub fn read_fn(name: &str) -> String {
    format!("read_{}", name.to_snake_case())
}

/// One emitted value: a call breaks at its arguments rather than at whatever
/// runs over first.
pub enum Value {
    Plain(String),
    Call {
        head: String,
        args: Vec<String>,
        /// What trails the call - a method chained onto what it answers.
        tail: String,
    },
}

impl Value {
    /// `<indent><binder> <value><tail>`, the value on its own lines when the
    /// one-liner runs over.
    pub fn write(
        &self,
        f: &mut impl Write,
        indent: &str,
        binder: &str,
        tail: &str,
    ) -> std::io::Result<()> {
        let one_line = format!("{}{} {}{}", indent, binder, self.rendered(), tail);
        if one_line.len() <= WIDTH {
            return writeln!(f, "{}", one_line);
        }
        match self {
            Value::Plain(value) => {
                writeln!(f, "{}{}", indent, binder)?;
                writeln!(f, "{}    {}{}", indent, value, tail)
            }
            Value::Call {
                head,
                args,
                tail: chained,
            } if chained.is_empty() => write_call(
                f,
                indent,
                &format!("{} {}(", binder, head),
                args,
                &format!("){}", tail),
            ),
            // A chained method goes on its own line: gluing it to the closing
            // paren of a broken call reads as neither.
            Value::Call {
                head,
                args,
                tail: chained,
            } => {
                write_call(f, indent, &format!("{} {}(", binder, head), args, ")")?;
                writeln!(f, "{}{}{}", indent, chained, tail)
            }
        }
    }

    fn rendered(&self) -> String {
        match self {
            Value::Plain(value) => value.clone(),
            Value::Call { head, args, tail } => format!("{}({}){}", head, args.join(", "), tail),
        }
    }
}

/// The name a a::b::Name path ends in, or the whole of a path that names no
/// module.
pub fn type_name(path: &str) -> &str {
    path.rsplit_once("::").map_or(path, |(_, name)| name)
}

/// The type names each module supplies, deduplicated, for a set of a::b::Name
/// paths.
pub fn group_imports<'a>(paths: impl Iterator<Item = &'a str>) -> BTreeMap<&'a str, Vec<&'a str>> {
    let mut imports: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    for path in paths {
        let (module, name) = path
            .rsplit_once("::")
            .expect("an import path names a module");
        imports.entry(module).or_default().insert(name);
    }
    imports
        .into_iter()
        .map(|(module, types)| (module, types.into_iter().collect()))
        .collect()
}

/// `use <module>::{<types>};`, broken across lines when it runs over.
pub fn write_use_list(f: &mut impl Write, module: &str, types: &[&str]) -> std::io::Result<()> {
    let one_line = match types {
        [only] => format!("use {}::{};", module, only),
        _ => format!("use {}::{{{}}};", module, types.join(", ")),
    };
    if one_line.len() <= WIDTH {
        return writeln!(f, "{}", one_line);
    }
    writeln!(f, "use {}::{{", module)?;
    let items: Vec<String> = types.iter().map(|ty| format!("{},", ty)).collect();
    write_wrapped(f, "   ", WIDTH, &items)?;
    writeln!(f, "}};")
}

/// `<head><params joined><tail>`, breaking one param per line when it runs over.
pub fn write_signature(
    f: &mut impl Write,
    head: &str,
    params: &[String],
    tail: &str,
) -> std::io::Result<()> {
    write_call(f, "", head, params, tail)
}

/// The same, indented: `<indent><head><args joined><tail>`, one argument per line
/// when the one-liner runs over.
pub fn write_call(
    f: &mut impl Write,
    indent: &str,
    head: &str,
    args: &[String],
    tail: &str,
) -> std::io::Result<()> {
    let one_line = format!("{}{}{}{}", indent, head, args.join(", "), tail);
    if one_line.len() <= WIDTH {
        return writeln!(f, "{}", one_line);
    }
    writeln!(f, "{}{}", indent, head)?;
    for arg in args {
        writeln!(f, "{}    {},", indent, arg)?;
    }
    writeln!(f, "{}{}", indent, tail)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn emitted(body: impl FnOnce(&mut Vec<u8>) -> std::io::Result<()>) -> String {
        let mut out = Vec::new();
        body(&mut out).expect("emit");
        String::from_utf8(out).expect("utf8")
    }

    #[test]
    fn a_single_import_needs_no_braces() {
        assert_eq!(
            emitted(|f| write_use_list(f, "crate::data", &["PartyView"])),
            "use crate::data::PartyView;\n"
        );
    }

    #[test]
    fn imports_that_fit_stay_on_one_line() {
        assert_eq!(
            emitted(|f| write_use_list(f, "crate::data", &["PartyView", "TermView"])),
            "use crate::data::{PartyView, TermView};\n"
        );
    }

    #[test]
    fn a_long_import_list_breaks_across_lines() {
        let types = [
            "AuthorView",
            "CompetitionView",
            "LinkView",
            "PartyDetailView",
            "PlacingEntryView",
            "ProductionCreditView",
            "ScreenshotView",
        ];

        assert_eq!(
            emitted(|f| write_use_list(f, "crate::demoscene::data", &types)),
            "use crate::demoscene::data::{\n\
             \x20   AuthorView, CompetitionView, LinkView, PartyDetailView, PlacingEntryView, \
             ProductionCreditView,\n\
             \x20   ScreenshotView,\n\
             };\n"
        );
    }

    #[test]
    fn a_signature_that_fits_stays_on_one_line() {
        assert_eq!(
            emitted(|f| write_signature(
                f,
                "pub fn read_party(",
                &["raw: &abi::Party".to_owned()],
                ") -> Party {"
            )),
            "pub fn read_party(raw: &abi::Party) -> Party {\n"
        );
    }

    #[test]
    fn a_signature_over_the_width_takes_one_param_per_line() {
        let params = [
            "view: &SomeRatherLongViewTypeNameThatPushesTheLineOver".to_owned(),
            "arena: *mut FlArena".to_owned(),
        ];

        assert_eq!(
            emitted(|f| write_signature(
                f,
                "pub(crate) unsafe fn publish_demozoo_production_detail(",
                &params,
                ") -> abi::DemozooProductionDetail {"
            )),
            "pub(crate) unsafe fn publish_demozoo_production_detail(\n\
             \x20   view: &SomeRatherLongViewTypeNameThatPushesTheLineOver,\n\
             \x20   arena: *mut FlArena,\n\
             ) -> abi::DemozooProductionDetail {\n"
        );
    }

    #[test]
    fn imports_group_by_module_and_deduplicate() {
        let paths = ["a::b::One", "a::b::Two", "c::Three", "a::b::One"];
        let grouped = group_imports(paths.into_iter());

        assert_eq!(grouped["a::b"], ["One", "Two"]);
        assert_eq!(grouped["c"], ["Three"]);
    }
}
